+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send", event -> send());
+    private final Grid<SentMessages.Message> grid = new Grid<>();
+    private final SentMessages sentMessages;
+    private Dialog leaveDialog;
+    private BeforeLeaveEvent.ContinueNavigationAction pendingNavigation;
+
+    public ContactView(SentMessages sentMessages) {
+        this.sentMessages = sentMessages;
+        setMaxWidth("60rem");
+
+        // Validate on Send, including EmailField's format check, so all failures
+        // use the same server-side validation path in a browser and in tests.
+        name.setManualValidation(true);
+        email.setManualValidation(true);
+        phone.setManualValidation(true);
+        message.setManualValidation(true);
+        for (TextFieldBase<?, String> field : fields()) {
+            // Keep navigation guards and Enter shortcuts in sync with typing,
+            // even when the user has not blurred the field yet.
+            field.setValueChangeMode(ValueChangeMode.EAGER);
+            field.addValueChangeListener(event -> send.setEnabled(true));
+        }
+
+        FormLayout form = new FormLayout();
+        form.setWidthFull();
+        form.setResponsiveSteps(new FormLayout.ResponsiveStep("0", 1),
+                new FormLayout.ResponsiveStep("36rem", 2));
+        form.add(name, 2);
+        form.add(email, phone);
+        form.add(message, 2);
+        send.addClickShortcut(Key.ENTER);
+
+        grid.addColumn(SentMessages.Message::name).setHeader("Name");
+        grid.addColumn(SentMessages.Message::message).setHeader("Message").setFlexGrow(2);
+        grid.setWidthFull();
+        grid.setHeight("18rem");
+        grid.setItems(sentMessages.findAll());
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class), form, send, grid);
+    }
+
+    private List<TextFieldBase<?, String>> fields() {
+        return List.of(name, email, phone, message);
+    }
+
+    private void send() {
+        if (!send.isEnabled()) {
+            return;
+        }
+
+        String nameError = name.getValue().isBlank() ? "Name is required" : null;
+        String emailError = null;
+        if (email.getValue().isBlank()) {
+            if (phone.getValue().isBlank()) {
+                emailError = "Give an e-mail address or a phone number";
+            }
+        } else if (new EmailValidator("Enter a valid e-mail address")
+                .apply(email.getValue(), new ValueContext(email)).isError()) {
+            emailError = "Enter a valid e-mail address";
+        }
+        String messageError = message.getValue().isBlank() ? "Message is required"
+                : message.getValue().length() > 500 ? "Message must be at most 500 characters" : null;
+
+        setError(name, nameError);
+        setError(email, emailError);
+        setError(message, messageError);
+        if (nameError != null || emailError != null || messageError != null) {
+            return;
+        }
+
+        sentMessages.send(name.getValue(), email.getValue(), phone.getValue(), message.getValue());
+        grid.setItems(sentMessages.findAll());
+        fields().forEach(TextFieldBase::clear);
+        send.setEnabled(false);
+        Notification.show("Message sent");
+    }
+
+    private void setError(TextFieldBase<?, String> field, String error) {
+        field.setErrorMessage(error);
+        field.setInvalid(error != null);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (fields().stream().allMatch(field -> field.getValue().isEmpty())) {
+            return;
+        }
+        if (pendingNavigation != null) {
+            pendingNavigation.cancel();
+            leaveDialog.close();
+        }
+        var navigation = event.postpone();
+        pendingNavigation = navigation;
+        Dialog dialog = new Dialog();
+        leaveDialog = dialog;
+        dialog.setHeaderTitle("Discard your message?");
+        dialog.add(new Paragraph("Your message has not been sent."));
+        dialog.setCloseOnEsc(false);
+        dialog.setCloseOnOutsideClick(false);
+        Button keepEditing = new Button("Keep editing", click -> {
+            navigation.cancel();
+            pendingNavigation = null;
+            dialog.close();
+        });
+        Button discard = new Button("Discard", click -> {
+            pendingNavigation = null;
+            dialog.close();
+            navigation.proceed();
+        });
+        dialog.getFooter().add(keepEditing, discard);
+        dialog.open();
+    }
+}
