+package com.example;
+
+import java.util.ArrayList;
+import java.util.List;
+import java.util.UUID;
+
+import org.springframework.stereotype.Service;
+
+/** Application-lifetime history, shared by successive visits to the contact view. */
+@Service
+public class SentMessages {
+    public record Message(UUID id, String name, String email, String phone, String message) {
+    }
+
+    private final List<Message> messages = new ArrayList<>();
+
+    public synchronized void send(String name, String email, String phone, String message) {
+        messages.addFirst(new Message(UUID.randomUUID(), name, email, phone, message));
+    }
+
+    public synchronized List<Message> findAll() {
+        return List.copyOf(messages);
+    }
+}
