+package com.example;
+
+import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
+import static org.junit.jupiter.api.Assertions.assertEquals;
+
+import java.util.List;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.element.DialogElement;
+import org.vaadin.addons.dramafinder.element.EmailFieldElement;
+import org.vaadin.addons.dramafinder.element.TextAreaElement;
+import org.vaadin.addons.dramafinder.element.TextFieldElement;
+
+import com.microsoft.playwright.Browser;
+import com.microsoft.playwright.BrowserType;
+import com.microsoft.playwright.Locator;
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.Playwright;
+import com.microsoft.playwright.options.AriaRole;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT,
+        properties = {"vaadin.launch-browser=false", "vaadin.frontend.hotdeploy=false"})
+class ContactBrowserTest {
+    @LocalServerPort
+    private int port;
+
+    @Test
+    void validatesSendsWithEnterAndProtectsDraftsInChromium() {
+        try (Playwright playwright = Playwright.create();
+                Browser browser = playwright.chromium().launch(new BrowserType.LaunchOptions()
+                        .setHeadless(true).setArgs(List.of("--no-sandbox")))) {
+            Page page = browser.newPage();
+            page.setDefaultTimeout(15000);
+            page.navigate("http://localhost:" + port + "/contact");
+            assertThat(page.locator("h1")).hasText("Contact");
+            page.evaluate("window.contactNavigationMarker = 'same-page'");
+
+            TextFieldElement name = TextFieldElement.getByLabel(page, "Name");
+            EmailFieldElement email = EmailFieldElement.getByLabel(page, "Email");
+            TextFieldElement phone = TextFieldElement.getByLabel(page, "Phone");
+            TextAreaElement message = TextAreaElement.getByLabel(page, "Message");
+            Locator send = button(page, "Send");
+            assertThat(send).isEnabled();
+            send.click();
+            name.assertErrorMessage("Name is required");
+            email.assertErrorMessage("Give an e-mail address or a phone number");
+            message.assertErrorMessage("Message is required");
+            assertThat(page.locator("vaadin-notification-card")).hasCount(0);
+
+            name.setValue("Browser sender");
+            phone.setValue("555-0199");
+            email.setValue("invalid");
+            message.setValue("Browser message");
+            send.click();
+            email.assertErrorMessage("Enter a valid e-mail address");
+            email.assertInvalid();
+            name.assertValue("Browser sender");
+            message.assertValue("Browser message");
+            email.clear();
+            message.setValue("x".repeat(501));
+            send.click();
+            message.assertErrorMessage("Message must be at most 500 characters");
+
+            message.setValue("Browser message");
+            message.getInputLocator().press("Enter");
+            assertThat(send).isDisabled();
+            assertThat(page.locator("vaadin-notification-card")).containsText("Message sent");
+            assertThat(page.locator("vaadin-grid")).containsText("Browser sender");
+            assertThat(page.locator("vaadin-grid")).containsText("Browser message");
+            name.assertValue("");
+            email.assertValue("");
+            phone.assertValue("");
+            message.assertValue("");
+            phone.setValue("1");
+            assertThat(send).isEnabled();
+            phone.clear();
+            assertThat(send).isEnabled();
+
+            page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About").setExact(true)).click();
+            assertThat(page.locator("h1")).hasText("About");
+            assertThat(page.getByRole(AriaRole.DIALOG)).hasCount(0);
+            assertEquals("same-page", page.evaluate("window.contactNavigationMarker"));
+            page.goBack();
+            assertThat(page.locator("h1")).hasText("Contact");
+            assertThat(page.locator("vaadin-grid")).containsText("Browser message");
+            assertThat(send).isEnabled();
+
+            // Every field must block immediate navigation while still focused.
+            for (TextFieldElement field : List.of(name, email, phone, message)) {
+                field.setValue("Draft");
+                page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About").setExact(true)).click();
+                new DialogElement(page).assertVisible();
+                assertThat(page.locator("h1")).hasText("Contact");
+                button(page, "Keep editing").click();
+                assertThat(page.getByRole(AriaRole.DIALOG)).hasCount(0);
+                field.assertValue("Draft");
+                field.clear();
+            }
+
+            message.setValue("Unsaved draft");
+            page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About").setExact(true)).click();
+            button(page, "Discard").click();
+            assertThat(page.locator("h1")).hasText("About");
+            assertEquals("same-page", page.evaluate("window.contactNavigationMarker"));
+        }
+    }
+
+    private Locator button(Page page, String text) {
+        return page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName(text).setExact(true));
+    }
+}
