+package com.example;
+
+import static org.junit.jupiter.api.Assertions.*;
+
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.junit.jupiter.params.ParameterizedTest;
+import org.junit.jupiter.params.provider.ValueSource;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+    private TextField name;
+    private EmailField email;
+    private TextField phone;
+    private TextArea message;
+    private Button send;
+
+    @BeforeEach
+    void openContact() {
+        navigate(ContactView.class);
+        name = $(TextField.class).withLabel("Name").single();
+        email = $(EmailField.class).withLabel("Email").single();
+        phone = $(TextField.class).withLabel("Phone").single();
+        message = $(TextArea.class).withLabel("Message").single();
+        send = $(Button.class).withText("Send").single();
+    }
+
+    @Test
+    void emptyFormValidatesAllRequiredFieldsWithoutSending() {
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertTrue(send.isEnabled());
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", phone.getValue());
+        assertEquals("", message.getValue());
+        int count = rowCount();
+        test(send).click();
+        assertTrue(name.isInvalid());
+        assertEquals("Name is required", name.getErrorMessage());
+        assertTrue(email.isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email.getErrorMessage());
+        assertTrue(message.isInvalid());
+        assertEquals("Message is required", message.getErrorMessage());
+        assertFalse(phone.isInvalid());
+        assertFalse($(Notification.class).exists());
+        assertEquals(count, rowCount());
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void rejectsMalformedEmailEvenWhenPhoneIsPresentAndPreservesInput() {
+        fillPhoneMessage();
+        test(email).setValue("not-an-address");
+        int count = rowCount();
+        test(send).click();
+        assertTrue(email.isInvalid());
+        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
+        assertEquals("Taylor", name.getValue());
+        assertEquals("not-an-address", email.getValue());
+        assertEquals("555-0123", phone.getValue());
+        assertEquals("Hello", message.getValue());
+        assertEquals(count, rowCount());
+        assertFalse($(Notification.class).exists());
+    }
+
+    @Test
+    void rejectsWhitespaceAndOverlongMessagesButAcceptsFiveHundredCharacters() {
+        fillPhoneMessage();
+        test(name).setValue("  ");
+        test(message).setValue(" \n ");
+        test(send).click();
+        assertEquals("Name is required", name.getErrorMessage());
+        assertEquals("Message is required", message.getErrorMessage());
+        test(name).setValue("Taylor");
+        test(message).setValue("x".repeat(501));
+        test(send).click();
+        assertTrue(message.isInvalid());
+        assertEquals("Message must be at most 500 characters", message.getErrorMessage());
+        test(message).setValue("x".repeat(500));
+        test(send).click();
+        assertFalse(message.isInvalid());
+        assertFalse(name.isInvalid());
+        assertFalse(send.isEnabled());
+    }
+
+    @Test
+    void sendsWithEitherContactMethodOrdersHistoryAndKeepsItAcrossVisits() {
+        int count = rowCount();
+        fillPhoneMessage();
+        test(send).click();
+        assertEquals(count + 1, rowCount());
+        assertEquals("Hello", test($(Grid.class).single()).getCellText(0, 1));
+        assertTrue(test($(Notification.class).single()).getText().contains("Message sent"));
+        assertClearedAndDisabled();
+        test(name).setValue("Morgan");
+        assertTrue(send.isEnabled());
+        test(email).setValue("morgan@example.com");
+        test(message).setValue("Second message");
+        fireShortcut(Key.ENTER);
+        assertEquals(count + 2, rowCount());
+        assertEquals("Morgan", test($(Grid.class).single()).getCellText(0, 0));
+        assertEquals("Second message", test($(Grid.class).single()).getCellText(0, 1));
+        assertEquals("Hello", test($(Grid.class).single()).getCellText(1, 1));
+        assertClearedAndDisabled();
+        test($(RouterLink.class).withText("About").single()).click();
+        assertFalse($(Dialog.class).exists());
+        assertEquals("About", $(H1.class).single().getText());
+        navigate(ContactView.class);
+        assertEquals(count + 2, rowCount());
+        assertEquals("Second message", test($(Grid.class).single()).getCellText(0, 1));
+        assertTrue($(Button.class).withText("Send").single().isEnabled());
+    }
+
+    @ParameterizedTest
+    @ValueSource(strings = {"Name", "Email", "Phone", "Message"})
+    void everyFieldGuardsRouterLinkAndProgrammaticNavigation(String field) {
+        switch (field) {
+            case "Name" -> test(name).setValue("Draft");
+            case "Email" -> test(email).setValue("draft@example.com");
+            case "Phone" -> test(phone).setValue("123");
+            case "Message" -> test(message).setValue("Draft message");
+        }
+        var values = java.util.List.of(name.getValue(), email.getValue(), phone.getValue(), message.getValue());
+        test($(RouterLink.class).single()).click();
+        assertTrue($(Dialog.class).single().isOpened());
+        assertInstanceOf(ContactView.class, getCurrentView());
+        test($(Button.class).withText("Keep editing").single()).click();
+        assertFalse($(Dialog.class).exists());
+        assertInstanceOf(ContactView.class, getCurrentView());
+        assertEquals(values, java.util.List.of(name.getValue(), email.getValue(), phone.getValue(), message.getValue()));
+        UI.getCurrent().navigate("about");
+        assertTrue($(Dialog.class).single().isOpened());
+        test($(Button.class).withText("Discard").single()).click();
+        assertEquals("About", $(H1.class).single().getText());
+        navigate(ContactView.class);
+        assertEquals("", $(TextArea.class).single().getValue());
+    }
+
+    @ParameterizedTest
+    @ValueSource(strings = {"Name", "Email", "Phone", "Message"})
+    void editingAnyFieldReenablesSendEvenIfThenCleared(String field) {
+        fillPhoneMessage();
+        test(send).click();
+        assertClearedAndDisabled();
+        switch (field) {
+            case "Name" -> { test(name).setValue("A"); test(name).clear(); }
+            case "Email" -> { test(email).setValue("a@example.com"); test(email).clear(); }
+            case "Phone" -> { test(phone).setValue("1"); test(phone).clear(); }
+            case "Message" -> { test(message).setValue("A"); test(message).clear(); }
+        }
+        assertTrue(send.isEnabled());
+        test(send).click();
+        assertTrue(name.isInvalid());
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void emptyOrManuallyClearedFormLeavesWithoutDialog() {
+        test(name).setValue(" ");
+        test(name).clear();
+        test($(RouterLink.class).single()).click();
+        assertFalse($(Dialog.class).exists());
+        assertEquals("About", $(H1.class).single().getText());
+    }
+
+    private void fillPhoneMessage() {
+        test(name).setValue("Taylor");
+        test(phone).setValue("555-0123");
+        test(message).setValue("Hello");
+    }
+
+    private void assertClearedAndDisabled() {
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", phone.getValue());
+        assertEquals("", message.getValue());
+        assertFalse(send.isEnabled());
+    }
+
+    private int rowCount() {
+        return test($(Grid.class).single()).size();
+    }
+}
